window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-473ecd66fe975ee4"]={"versions": [{"id": "FIG-473ecd66fe975ee4", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P06Check()</code> innerhalb des AUTOSAR E2E Protocol (Profil 6). Das Diagramm beschreibt den Teilschritt „Read CRC“ beim Empfang und der Prüfung von E2E-geschützten Nutzdaten auf Empfängerseite (Classic und Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext-Aktion / Rahmen:</strong> Aufrufkontext <code>E2E_P06Check()</code> mit Invocation-Symbol.\n</li><li><strong>Startknoten (Initial Node):</strong> Beginn der Teilaktivität zur Extraktion der Prüfsumme.\n</li><li><strong>Aktionsknoten:</strong> <code>Copy bytes Data[Offset+0...Offset+1] using big Endian order on 2-byte local variable ReceivedCRC</code>.\n</li><li><strong>Endknoten (Activity Final Node):</strong> Regulärer Abschluss des Teilschritts.\n</li><li><strong>Daten- und Schnittstellenelemente:</strong>\n<ul class=\"fig-list\"><li>Eingangsarray <code>Data[]</code>: Serialisierter Datenpuffer der Nachricht.\n</li><li>Konfigurationsparameter <code>Offset</code>: Bit- bzw. Byte-Versatz im Datenstrom.\n</li><li>Lokale Variable <code>ReceivedCRC</code>: 2-Byte breite Variable (entspricht <code>uint16</code>) zur Aufnahme des aus dem Datenstrom extrahierten CRC-Werts.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt in den Teilschritt über den Startknoten.\n</li><li>Ausführung der Kopieraktion: Aus dem Datenpuffer <code>Data</code> werden beginnend bei <code>Offset + 0</code> bis <code>Offset + 1</code> zwei zusammenhängende Bytes ausgelesen.\n</li><li>Konvertierung/Zuweisung: Die zwei Bytes werden unter Verwendung der Byte-Reihenfolge Big Endian in die 2-Byte-Variable <code>ReceivedCRC</code> übertragen.\n</li><li>Übergang zum Endknoten zur Fortsetzung der nachfolgenden Prüfschritte innerhalb von <code>E2E_P06Check()</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung gemäß <code>[PRS_E2E_00434]</code>:</p>\n<ul class=\"fig-list\"><li>Das CRC-Feld in Profil 6 ist exakt 2 Bytes lang (16-Bit CRC, CRC-16).\n</li><li>Die Positionierung erfolgt an den relativen Byte-Indizes 0 und 1 ab <code>Offset</code>.\n</li><li>Die Dekodierung in die lokale Variable muss zwingend in Big-Endian-Bytereihenfolge (<code>Data[Offset]</code> als Most Significant Byte, <code>Data[Offset+1]</code> als Least Significant Byte) erfolgen, unabhängig von der nativen Endianness des Ziel-Mikrocontrollers bzw. Host-Systems.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-641ea8f05cb0884a", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P06Check()</code> innerhalb des AUTOSAR E2E Protocol (Profil 6). Das Diagramm beschreibt den Teilschritt „Read CRC“ beim Empfang und der Prüfung von E2E-geschützten Nutzdaten auf Empfängerseite (Classic und Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext-Aktion / Rahmen:</strong> Aufrufkontext <code>E2E_P06Check()</code> mit Invocation-Symbol.\n</li><li><strong>Startknoten (Initial Node):</strong> Beginn der Teilaktivität zur Extraktion der Prüfsumme.\n</li><li><strong>Aktionsknoten:</strong> <code>Copy bytes Data[Offset+0...Offset+1] using big Endian order on 2-byte local variable ReceivedCRC</code>.\n</li><li><strong>Endknoten (Activity Final Node):</strong> Regulärer Abschluss des Teilschritts.\n</li><li><strong>Daten- und Schnittstellenelemente:</strong>\n<ul class=\"fig-list\"><li>Eingangsarray <code>Data[]</code>: Serialisierter Datenpuffer der Nachricht.\n</li><li>Konfigurationsparameter <code>Offset</code>: Bit- bzw. Byte-Versatz im Datenstrom.\n</li><li>Lokale Variable <code>ReceivedCRC</code>: 2-Byte breite Variable (entspricht <code>uint16</code>) zur Aufnahme des aus dem Datenstrom extrahierten CRC-Werts.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt in den Teilschritt über den Startknoten.\n</li><li>Ausführung der Kopieraktion: Aus dem Datenpuffer <code>Data</code> werden beginnend bei <code>Offset + 0</code> bis <code>Offset + 1</code> zwei zusammenhängende Bytes ausgelesen.\n</li><li>Konvertierung/Zuweisung: Die zwei Bytes werden unter Verwendung der Byte-Reihenfolge Big Endian in die 2-Byte-Variable <code>ReceivedCRC</code> übertragen.\n</li><li>Übergang zum Endknoten zur Fortsetzung der nachfolgenden Prüfschritte innerhalb von <code>E2E_P06Check()</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung gemäß <code>[PRS_E2E_00434]</code>:</p>\n<ul class=\"fig-list\"><li>Das CRC-Feld in Profil 6 ist exakt 2 Bytes lang (16-Bit CRC, CRC-16).\n</li><li>Die Positionierung erfolgt an den relativen Byte-Indizes 0 und 1 ab <code>Offset</code>.\n</li><li>Die Dekodierung in die lokale Variable muss zwingend in Big-Endian-Bytereihenfolge (<code>Data[Offset]</code> als Most Significant Byte, <code>Data[Offset+1]</code> als Least Significant Byte) erfolgen, unabhängig von der nativen Endianness des Ziel-Mikrocontrollers bzw. Host-Systems.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-473ecd66fe975ee4", "to": "FIG-641ea8f05cb0884a", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
